const fields=(value:string)=>value.split(";");
export const providerProfilesFourth:Record<string,ProviderProfile>=Object.fromEntries(Object.entries(rows).map(([name,[officialUrl,de,en,fd,fe,rd,re]])=>[name,{
  officialUrl,officialLabel:{de:`Offizielle Anbieterquelle: ${name}`,en:`Official provider source: ${name}`},
  metaDescription:{de:de.split(". ")[0]+".",en:en.split(". ")[0]+"."},
  summary:{de,en},focus:{de:fields(fd),en:fields(fe)},buyerGroups:{de:fields(rd),en:fields(re)}
}]));
